#!/usr/bin/env python3
# per agent of a Workflow run: label, id, writes, first-call writes, turns, minutes, UTC span;
# and the index of tool calls matching a pattern (bounded output, no transcript text printed beyond a short command head)
import json, glob, os, sys, re
from datetime import datetime

def ts(s):
    return datetime.fromisoformat(s.replace('Z', '+00:00'))

run = sys.argv[1]
mode = sys.argv[2] if len(sys.argv) > 2 else 'table'
pat = re.compile(sys.argv[3]) if len(sys.argv) > 3 else None
rows = []
for f in glob.glob(os.path.join(run, 'agent-*.jsonl')):
    aid = os.path.basename(f)[6:-6]
    meta = json.load(open(f[:-6] + '.meta.json'))
    label = meta.get('description')
    seen = {}
    order = []
    times = []
    calls = []  # (index, ts, name, cmdhead, msgid)
    results = {}
    for line in open(f, errors='replace'):
        try:
            r = json.loads(line)
        except Exception:
            continue
        t = r.get('timestamp')
        if t:
            times.append(ts(t))
        m = r.get('message') if isinstance(r.get('message'), dict) else None
        if not m:
            continue
        if m.get('role') == 'assistant' and m.get('usage'):
            mid = m.get('id') or id(m)
            if mid not in seen:
                order.append(mid)
            seen[mid] = m['usage']
            for c in m.get('content') or []:
                if isinstance(c, dict) and c.get('type') == 'tool_use':
                    inp = c.get('input') or {}
                    head = inp.get('command') or inp.get('file_path') or inp.get('skill') or inp.get('pattern') or ''
                    calls.append((len(calls) + 1, t, c.get('name'), str(head), mid, c.get('id')))
        if m.get('role') == 'user' and isinstance(m.get('content'), list):
            for c in m['content']:
                if isinstance(c, dict) and c.get('type') == 'tool_result':
                    cc = c.get('content')
                    txt = cc if isinstance(cc, str) else ' '.join(x.get('text', '') for x in cc if isinstance(x, dict)) if isinstance(cc, list) else ''
                    results[c.get('tool_use_id')] = (txt, c.get('is_error'))
    w = lambda u: u.get('input_tokens', 0) + u.get('cache_creation_input_tokens', 0)
    tot = sum(w(u) for u in seen.values())
    first = w(seen[order[0]]) if order else 0
    firstread = seen[order[0]].get('cache_read_input_tokens', 0) if order else 0
    # first turn = calls in first message id
    ft = [c for c in calls if c[4] == order[0]] if order else []
    rows.append(dict(label=label, id=aid, tot=tot, first=first, firstread=firstread, turns=len(order),
                     start=min(times), end=max(times), calls=calls, results=results, ft=ft))
rows.sort(key=lambda r: r['start'])
if mode == 'table':
    T = 0
    for r in rows:
        T += r['tot']
        mins = (r['end'] - r['start']).total_seconds() / 60
        print(f"{r['label']:12} {r['id'][:8]} {r['tot']/1e3:7.0f}K first {r['first']/1e3:5.0f}K (read {r['firstread']/1e3:5.0f}K) turns {r['turns']:4} calls {len(r['calls']):4} {mins:6.1f} min {r['start'].strftime('%H:%M')}-{r['end'].strftime('%H:%M')} firstturn={[c[2] for c in r['ft']]}")
    print(f"TOTAL {T/1e6:.3f}M over {len(rows)}")
elif mode == 'grep':
    # calls whose command head matches pat
    for r in rows:
        hits = [c for c in r['calls'] if pat.search(c[3])]
        if hits:
            print(f"== {r['label']} {r['id'][:8]} ({len(hits)})")
            for c in hits[:int(os.environ.get('MAXH', '12'))]:
                print(f"  #{c[0]} {c[1][11:19] if c[1] else ''} {c[2]} {c[3][:160].replace(chr(10),' | ')}")
elif mode == 'rgrep':
    # calls whose result matches pat
    for r in rows:
        hits = []
        for c in r['calls']:
            res = r['results'].get(c[5])
            if res and pat.search(res[0] or ''):
                mm = pat.search(res[0])
                hits.append((c, res[0][max(0, mm.start()-60):mm.end()+80].replace('\n', ' | '), res[1]))
        if hits:
            print(f"== {r['label']} {r['id'][:8]} ({len(hits)})")
            for c, snip, err in hits[:int(os.environ.get('MAXH', '12'))]:
                print(f"  #{c[0]} {c[1][11:19] if c[1] else ''} {c[2]} err={err} cmd={c[3][:80].replace(chr(10),' | ')} :: {snip[:220]}")

